-- ATOM Phase 1 — initial schema: users and refresh sessions.
--
-- Conventions:
--   * Primary keys are UUIDv4 generated by the application layer, so that the
--     API never exposes sequential identifiers.
--   * `timestamptz` is used for every timestamp; the API renders RFC 3339 UTC.
--   * Ownership is enforced by a non-null `user_id` foreign key. Every query in
--     the application layer filters on the authenticated user id.
--   * Deletes cascade for strictly-owned data and restrict where a parent must
--     survive its children (projects -> tasks is handled explicitly in the
--     service layer, see docs/database/migration-policy.md).

CREATE TABLE users (
    id            UUID        PRIMARY KEY,
    -- Normalized (trimmed, lower-cased) email address. Uniqueness is enforced
    -- by the database so that concurrent registrations cannot race.
    email         TEXT        NOT NULL,
    password_hash TEXT        NOT NULL,
    display_name  TEXT        NOT NULL,
    is_active     BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT users_email_normalized_chk CHECK (email = LOWER(BTRIM(email))),
    CONSTRAINT users_email_length_chk   CHECK (CHAR_LENGTH(email) BETWEEN 3 AND 254),
    CONSTRAINT users_display_name_chk   CHECK (CHAR_LENGTH(display_name) BETWEEN 1 AND 120)
);

-- Uniqueness lives on the normalized value, not on a functional index, so that
-- the constraint is visible to SQLx, to migrations and to plain SQL clients.
CREATE UNIQUE INDEX users_email_unique_idx ON users (email);

-- Refresh sessions: one row per issued refresh token.
--
-- Only the SHA-256 hash of the token is persisted. A database leak therefore
-- does not yield usable refresh tokens.
CREATE TABLE refresh_sessions (
    id                       UUID        PRIMARY KEY,
    user_id                  UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- SHA-256 hash of the opaque refresh token, hex encoded.
    token_hash               TEXT        NOT NULL,
    expires_at               TIMESTAMPTZ NOT NULL,
    revoked_at               TIMESTAMPTZ,
    created_at               TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- Rotation link: when a refresh token is exchanged, the new session points
    -- back at the session it replaced. Reuse of an already-rotated token is
    -- detected by finding a row whose id is referenced here.
    replaced_by_session_id   UUID        REFERENCES refresh_sessions (id) ON DELETE SET NULL,
    user_agent               TEXT,
    ip_address               TEXT
);

CREATE UNIQUE INDEX refresh_sessions_token_hash_unique_idx ON refresh_sessions (token_hash);
CREATE INDEX refresh_sessions_user_id_idx ON refresh_sessions (user_id);
-- Supports the "revoke every session for this user" operation.
CREATE INDEX refresh_sessions_active_idx ON refresh_sessions (user_id) WHERE revoked_at IS NULL;
